```cuda
// Each block handles one (batch, seq) position
// Threads handle all (head, pair_idx) pairs, with striding if needed
template <typename scalar_t>
__global__ void rotary_embedding_kernel(
    scalar_t* __restrict__ x,
    const int* __restrict__ positions,
    int seq_len,
    int num_heads,
    int head_dim,
    float base,
    int total_positions  // batch * seq_len
) {
    int pos_idx = blockIdx.x;  // which (batch, seq) position
    if (pos_idx >= total_positions) return;

    int batch = pos_idx / seq_len;
    int seq = pos_idx % seq_len;
    int half_dim = head_dim / 2;

    // Precompute cos/sin for all pair_idx values
    __shared__ float s_cos[64];  // max half_dim
    __shared__ float s_sin[64];

    int m = positions[pos_idx];

    // First half_dim threads compute cos/sin
    for (int pi = threadIdx.x; pi < half_dim; pi += blockDim.x) {
        float theta = static_cast<float>(1.0 / pow(static_cast<double>(base), (2.0 * pi) / head_dim));
        float angle = static_cast<float>(m) * theta;
        double sin_d, cos_d;
        sincos(static_cast<double>(angle), &sin_d, &cos_d);
        s_cos[pi] = static_cast<float>(cos_d);
        s_sin[pi] = static_cast<float>(sin_d);
    }
    __syncthreads();

    // Now apply rotation for all (head, pair_idx) combinations
    int total_pairs = num_heads * half_dim;
    for (int idx = threadIdx.x; idx < total_pairs; idx += blockDim.x) {
        int pair_idx = idx % half_dim;
        int head = idx / half_dim;

        int base_idx = ((batch * seq_len + seq) * num_heads + head) * head_dim;
        int i0 = base_idx + pair_idx;
        int i1 = base_idx + pair_idx + half_dim;

        float x0 = static_cast<float>(x[i0]);
        float x1 = static_cast<float>(x[i1]);

        float cos_val = s_cos[pair_idx];
        float sin_val = s_sin[pair_idx];

        x[i0] = static_cast<scalar_t>(x0 * cos_val - x1 * sin_val);
        x[i1] = static_cast<scalar_t>(x1 * cos_val + x0 * sin_val);
    }
}
```

This reduces the number of pow+sincos calls by a factor of num_heads (32x). For half_dim=32, we only need 32 sincos calls per (batch, seq) instead of 32*32=1024.

