template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    constexpr int VEC = 4;  // process 4 fp16 values at once
    int vec_hidden = hidden_size / VEC;

    // Vectorized sum of squares
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < vec_hidden; i += blockDim.x) {
        float4 vals = __ldg(reinterpret_cast<const float4*>(x))[i];
        // Extract 4 fp16 values and square them
        half2* h2_ptr = reinterpret_cast<half2*>(&vals);
        float2 f0 = __half22float2(h2_ptr[0]);
        float2 f1 = __half22float2(h2_ptr[1]);
        sum_sq += f0.x * f0.x + f0.y * f0.y + f1.x * f1.x + f1.y * f1.y;
    }
    // Handle remaining elements if hidden_size % VEC != 0
    for (int i = threadIdx.x + vec_hidden * VEC; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
    }

    // ... same reduction as before ...

    // Vectorized normalize and scale
    for (int i = threadIdx.x; i < vec_hidden; i += blockDim.x) {
        float4 vals = __ldg(reinterpret_cast<const float4*>(x))[i];
        float4 wvals = __ldg(reinterpret_cast<const float4*>(weight))[i];  // wait, weight isn't indexed by row
        // Actually weight is the same for all rows, so we can use the same indexing

        half2* h2_ptr = reinterpret_cast<half2*>(&vals);
        half2* w2_ptr = reinterpret_cast<half2*>(&wvals);

        float2 f0 = __half22float2(h2_ptr[0]);
        float2 f1 = __half22float2(h2_ptr[1]);
        float2 w0 = __half22float2(w2_ptr[0]);
        float2 w1 = __half22float2(w2_ptr[1]);

        f0.x = f0.x * rms_inv * w0.x;
        f0.y = f0.y * rms_inv * w0.y;
        f1.x = f1.x * rms_inv * w1.x;
        f1.y = f1.y * rms_inv * w1.y;

        // Store back
        float4 out;
        half2* oh2 = reinterpret_cast<half2*>(&out);
        oh2[0] = __float22half2_rn(f0);
        oh2[1] = __float22half2_rn(f1);
        reinterpret_cast<float4*>(o)[i] = out;
    }
}
