```cuda
template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    float sum_sq = 0.0f;

    // Use half2 vectorized loads for fp16
    if constexpr (std::is_same_v<scalar_t, at::Half>) {
        const half2* x_h2 = reinterpret_cast<const half2*>(x);
        int h2_size = hidden_size / 2;
        for (int i = threadIdx.x; i < h2_size; i += blockDim.x) {
            half2 val = __ldg(&x_h2[i]);
            float2 f = __half22float2(val);
            sum_sq += f.x * f.x + f.y * f.y;
        }
    } else {
        for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
            float val = static_cast<float>(__ldg(&x[i]));
            sum_sq += val * val;
        }
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (threadIdx.x == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    // Normalize and scale with vectorized loads/stores
    if constexpr (std::is_same_v<scalar_t, at::Half>) {
        const half2* x_h2 = reinterpret_cast<const half2*>(x);
        const half2* w_h2 = reinterpret_cast<const half2*>(weight);
        half2* o_h2 = reinterpret_cast<half2*>(o);
        int h2_size = hidden_size / 2;
        for (int i = threadIdx.x; i < h2_size; i += blockDim.x) {
            half2 val = __ldg(&x_h2[i]);
            half2 w = __ldg(&w_h2[i]);
            float2 f_val = __half22float2(val);
            float2 f_w = __half22float2(w);
            float2 f_out;
            f_out.x = f_val.x * rms_inv * f_w.x;
            f_out.y = f_val.y * rms_inv * f_w.y;
            o_h2[i] = __float22half2_rn(f_out);
        }
        // Handle odd element
        if (hidden_size & 1) {
            int i = hidden_size - 1;
            if (i >= threadIdx.x * 2 && i < (threadIdx.x + 1) * 2) {
                // This is a bit tricky, let me just use scalar for the last element
                float val = static_cast<float>(__ldg(&x[i]));
                float w = static_cast<float>(__ldg(&weight[i]));
                o[i] = static_cast<scalar_t>(val * rms_inv * w);
            }
        }
    } else {
        for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
            float val = static_cast<float>(__ldg(&x[i]));
            float w = static_cast<float>(__ldg(&weight[i]));
            o[i] = static_cast<scalar_t>(val * rms_inv * w);
        }
    }
}
